-- `DROP DEFAULT` is the way in: the clause is accepted after it, and the column draws
-- from the identity's sequence.
-- @setup
CREATE TABLE aid (c INT NOT NULL DEFAULT 5, v TEXT);
INSERT INTO aid (v) VALUES ('five');
ALTER TABLE aid ALTER COLUMN c DROP DEFAULT;
ALTER TABLE aid ALTER COLUMN c ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 10);
INSERT INTO aid (v) VALUES ('minted');
-- @test
SELECT c, v FROM aid ORDER BY c;
